CREATE TABLE IF NOT EXISTS typed_values (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    label TEXT NOT NULL,
    date_value DATE,
    timestamp_value TIMESTAMPTZ,
    amount NUMERIC(12, 2),
    enabled BOOLEAN,
    metadata JSONB,
    payload BYTEA,
    optional_text TEXT
);

INSERT INTO typed_values VALUES (1, 'json-object', '2024-02-29', '2024-02-29 23:59:59.123456+03', 123456.78, TRUE, '{"kind":"nested","tags":["json","café"],"valid":true,"count":3}'::jsonb, decode('00ff10a5', 'hex'), 'обычный текст')
ON CONFLICT (id) DO NOTHING;
INSERT INTO typed_values VALUES (2, 'json-null', NULL, NULL, NULL, FALSE, 'null'::jsonb, NULL, NULL)
ON CONFLICT (id) DO NOTHING;
INSERT INTO typed_values VALUES (3, 'empty-values', '2000-01-01', '2000-01-01 00:00:00+00', 0.00, FALSE, '{}'::jsonb, decode('', 'hex'), '')
ON CONFLICT (id) DO NOTHING;
INSERT INTO typed_values VALUES (4, 'large-text', '2038-01-19', '2038-01-19 03:14:07+00', -9876.50, TRUE, '{"description":"long text"}'::jsonb, decode('deadbeef', 'hex'), repeat('длинный-текст-', 120))
ON CONFLICT (id) DO NOTHING;
INSERT INTO typed_values VALUES (5, 'unicode', '1999-12-31', '1999-12-31 23:30:00-05', 0.01, TRUE, '{"город":"Токио","эмодзи":"🛰️","массив":[1,2,3]}'::jsonb, decode('cafe', 'hex'), 'Кириллица, العربية, 日本語')
ON CONFLICT (id) DO NOTHING;
INSERT INTO typed_values VALUES (6, 'precision', '2026-10-16', '2026-10-16 16:42:08.002001+03', 99999999.99, FALSE, '[1,"two",null,true]'::jsonb, decode('0123456789abcdef', 'hex'), 'точность времени и суммы')
ON CONFLICT (id) DO NOTHING;
INSERT INTO typed_values VALUES (7, 'negative', '1970-01-01', '1970-01-01 00:00:00+00', -0.01, NULL, '{"negative":-42,"fraction":3.14159}'::jsonb, decode('ff', 'hex'), 'NULL отдельно в bool')
ON CONFLICT (id) DO NOTHING;
INSERT INTO typed_values VALUES (8, 'leap-day', '2020-02-29', '2020-02-29 12:34:56.789+00', 42.42, TRUE, '{"nested":{"key":"value"},"spaces":"a b c"}'::jsonb, decode('0100ff', 'hex'), 'високосная дата')
ON CONFLICT (id) DO NOTHING;
